messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Red vs Blue — Drag Race</title>
<style>
  html, body { margin: 0; height: 100%; overflow: hidden; background: #87ceeb; }
  canvas { display: block; }
</style>
</head>
<body>
<script type="module">
import * as THREE from './three.module.js';

// ---------- Renderer / Scene / Camera ----------
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
document.body.appendChild(renderer.domElement);

const scene = new THREE.Scene();
scene.background = new THREE.Color(0x87ceeb);
scene.fog = new THREE.Fog(0x87ceeb, 300, 900);

const camera = new THREE.PerspectiveCamera(55, window.innerWidth / window.innerHeight, 0.1, 2000);

// ---------- Lights ----------
scene.add(new THREE.HemisphereLight(0xbfe3ff, 0x4a5a3a, 0.9));
const sun = new THREE.DirectionalLight(0xffffff, 1.4);
sun.position.set(60, 120, 80);
sun.castShadow = true;
sun.shadow.mapSize.set(2048, 2048);
sun.shadow.camera.left = -80;
sun.shadow.camera.right = 80;
sun.shadow.camera.top = 80;
sun.shadow.camera.bottom = -80;
sun.shadow.camera.far = 400;
scene.add(sun);

// ---------- Ground ----------
const groundGeo = new THREE.PlaneGeometry(4000, 4000);
const groundMat = new THREE.MeshLambertMaterial({ color: 0x6aa84f });
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.receiveShadow = true;
scene.add(ground);

// ---------- Track ----------
const TRACK_HALF_WIDTH = 14;   // track spans x in [-14, 14]
const FINISH_Z = 600;          // finish line at z = 600
const trackGeo = new THREE.PlaneGeometry(TRACK_HALF_WIDTH * 2, FINISH_Z + 400);
const trackMat = new THREE.MeshLambertMaterial({ color: 0x3a3a3e });
const track = new THREE.Mesh(trackGeo, trackMat);
track.rotation.x = -Math.PI / 2;
track.position.set(0, 0.02, (FINISH_Z + 400) / 2 - 200);
track.receiveShadow = true;
scene.add(track);

// Center dashed line
const dashMat = new THREE.MeshBasicMaterial({ color: 0xf5f5f5 });
for (let z = -180; z < FINISH_Z + 150; z += 20) {
  const dash = new THREE.Mesh(new THREE.PlaneGeometry(0.5, 10), dashMat);
  dash.rotation.x = -Math.PI / 2;
  dash.position.set(0, 0.04, z + 5);
  scene.add(dash);
}

// Edge lines
const edgeMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
for (const x of [-TRACK_HALF_WIDTH + 0.5, TRACK_HALF_WIDTH - 0.5]) {
  const edge = new THREE.Mesh(new THREE.PlaneGeometry(0.8, FINISH_Z + 400), edgeMat);
  edge.rotation.x = -Math.PI / 2;
  edge.position.set(x, 0.04, (FINISH_Z + 400) / 2 - 200);
  scene.add(edge);
}

// ---------- Finish line (checkered) ----------
const finishGroup = new THREE.Group();
const sq = 2;
for (let i = 0; i < TRACK_HALF_WIDTH * 2 / sq; i++) {
  for (let j = 0; j < 2; j++) {
    const c = (i + j) % 2 === 0 ? 0xffffff : 0x111111;
    const tile = new THREE.Mesh(
      new THREE.PlaneGeometry(sq, sq),
      new THREE.MeshBasicMaterial({ color: c })
    );
    tile.rotation.x = -Math.PI / 2;
    tile.position.set(-TRACK_HALF_WIDTH + sq / 2 + i * sq, 0.06, FINISH_Z + sq / 2 + j * sq);
    finishGroup.add(tile);
  }
}
// Finish gantry posts + banner
const postMat = new THREE.MeshLambertMaterial({ color: 0x222222 });
const postL = new THREE.Mesh(new THREE.CylinderGeometry(0.6, 0.6, 12, 12), postMat);
postL.position.set(-TRACK_HALF_WIDTH - 1, 6, FINISH_Z);
const postR = postL.clone();
postR.position.x = TRACK_HALF_WIDTH + 1;
const beam = new THREE.Mesh(new THREE.BoxGeometry(TRACK_HALF_WIDTH * 2 + 4, 2, 1), postMat);
beam.position.set(0, 12, FINISH_Z);
const banner = new THREE.Mesh(
  new THREE.PlaneGeometry(TRACK_HALF_WIDTH * 2 + 3, 1.8),
  new THREE.MeshBasicMaterial({ color: 0xffd54f, side: THREE.DoubleSide })
);
banner.position.set(0, 12, FINISH_Z - 0.6);
finishGroup.add(postL, postR, beam, banner);
scene.add(finishGroup);

// ---------- Car factory ----------
function makeCar(color) {
  const g = new THREE.Group();

  const bodyMat = new THREE.MeshStandardMaterial({ color, roughness: 0.35, metalness: 0.4 });
  // Main body
  const body = new THREE.Mesh(new THREE.BoxGeometry(2.6, 0.9, 5.6), bodyMat);
  body.position.y = 0.85;
  body.castShadow = true;
  // Cabin
  const cabin = new THREE.Mesh(new THREE.BoxGeometry(2.0, 0.75, 2.4), bodyMat);
  cabin.position.set(0, 1.6, -0.3);
  cabin.castShadow = true;
  // Windshield
  const glass = new THREE.Mesh(
    new THREE.BoxGeometry(1.9, 0.6, 0.15),
    new THREE.MeshStandardMaterial({ color: 0x9fd6ff, roughness: 0.1, metalness: 0.6 })
  );
  glass.position.set(0, 1.55, 0.95);
  glass.rotation.x = -0.45;
  // Spoiler
  const spoiler = new THREE.Mesh(new THREE.BoxGeometry(2.4, 0.12, 0.7), bodyMat);
  spoiler.position.set(0, 1.6, -2.7);
  const spPost1 = new THREE.Mesh(new THREE.BoxGeometry(0.12, 0.5, 0.12), bodyMat);
  spPost1.position.set(-0.9, 1.3, -2.7);
  const spPost2 = spPost1.clone();
  spPost2.position.x = 0.9;
  // Wheels
  const wheelGeo = new THREE.CylinderGeometry(0.55, 0.55, 0.45, 18);
  const wheelMat = new THREE.MeshStandardMaterial({ color: 0x151515, roughness: 0.9 });
  const hubGeo = new THREE.CylinderGeometry(0.25, 0.25, 0.47, 12);
  const hubMat = new THREE.MeshStandardMaterial({ color: 0xcccccc, roughness: 0.3, metalness: 0.8 });
  const wheels = [];
  const positions = [[-1.35, 1.7], [1.35, 1.7], [-1.35, -1.8], [1.35, -1.8]];
  for (const [wx, wz] of positions) {
    const w = new THREE.Mesh(wheelGeo, wheelMat);
    w.rotation.z = Math.PI / 2;
    w.position.set(wx, 0.55, wz);
    w.castShadow = true;
    const hub = new THREE.Mesh(hubGeo, hubMat);
    hub.rotation.z = Math.PI / 2;
    hub.position.set(wx, 0.55, wz);
    w.add(hub);
    wheels.push(w);
    g.add(w);
  }
  // Headlights
  const lightMat = new THREE.MeshBasicMaterial({ color: 0xfff9c4 });
  const hl1 = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.25, 0.1), lightMat);
  hl1.position.set(-0.85, 0.95, 2.82);
  const hl2 = hl1.clone();
  hl2.position.x = 0.85;
  // Taillights
  const tailMat = new THREE.MeshBasicMaterial({ color: 0xff2200 });
  const tl1 = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.2, 0.1), tailMat);
  tl1.position.set(-0.85, 0.95, -2.82);
  const tl2 = tl1.clone();
  tl2.position.x = 0.85;

  g.add(body, cabin, glass, spoiler, spPost1, spPost2, hl1, hl2, tl1, tl2);
  g.userData.wheels = wheels;
  return g;
}

const RED_LANE = -5.5;
const BLUE_LANE = 5.5;
const redCar = makeCar(0xff1a1a);
const blueCar = makeCar(0x1a5cff);
redCar.position.set(RED_LANE, 0, 0);
blueCar.position.set(BLUE_LANE, 0, 0);
scene.add(redCar, blueCar);

// ---------- Race logic ----------
const RACE_TIME = 14;          // seconds of racing
const RESET_TIME = 2.0;        // pause at finish before reset
let t = 0;

function easeInCubic(x) { return x * x * x; }

// Blue: quick start, then plateaus (loses). Red: slow start, strong finish (wins).
function blueProgress(p) { // p in [0,1] of race time
  return Math.min(1, easeInCubic(Math.min(p / 0.62, 1)) * 1.0);
}
function redProgress(p) {
  if (p < 0.35) {
    // slower early phase
    return easeInCubic(p / 0.35) * 0.18;
  }
  const q = (p - 0.35) / 0.65;
  // accelerate hard, reach 1.0 at p=1
  return 0.18 + 0.82 * easeInCubic(q);
}

function resetCars() {
  redCar.position.set(RED_LANE, 0, 0);
  blueCar.position.set(BLUE_LANE, 0, 0);
  redCar.rotation.y = 0;
  blueCar.rotation.y = 0;
}

function spinWheels(car, speed) {
  for (const w of car.userData.wheels) w.rotation.x -= speed;
}

// ---------- Camera follow ----------
function updateCamera() {
  const leadZ = Math.max(redCar.position.z, blueCar.position.z);
  const camZ = leadZ - 26;
  const camY = 11;
  const midX = (redCar.position.x + blueCar.position.x) / 2;
  camera.position.set(midX * 0.6, camY, camZ);
  const lookZ = leadZ + 14;
  camera.lookAt(midX * 0.6, 2.0, lookZ);
}

// ---------- Loop ----------
const clock = new THREE.Clock();
function animate() {
  requestAnimationFrame(animate);
  const dt = Math.min(clock.getDelta(), 0.05);
  t += dt;

  if (t < RACE_TIME) {
    const p = t / RACE_TIME;
    const bz = blueProgress(p) * FINISH_Z;
    const rz = redProgress(p) * FINISH_Z;
    blueCar.position.z = bz;
    redCar.position.z = rz;

    // slight body tilt with acceleration feel
    const rv = (redProgress(Math.min(p + 0.01, 1)) - redProgress(p)) * FINISH_Z;
    const bv = (blueProgress(Math.min(p + 0.01, 1)) - blueProgress(p)) * FINISH_Z;
    redCar.rotation.x = THREE.MathUtils.clamp(rv * 0.15, -0.06, 0.06);
    blueCar.rotation.x = THREE.MathUtils.clamp(bv * 0.15, -0.06, 0.06);

    spinWheels(redCar, rv * 0.9);
    spinWheels(blueCar, bv * 0.9);
  } else if (t < RACE_TIME + RESET_TIME) {
    // cars idle past the finish, decelerating
    const q = (t - RACE_TIME) / RESET_TIME;
    const drift = (1 - q) * (1 - q) * 30;
    redCar.position.z = FINISH_Z + drift + 6;
    blueCar.position.z = FINISH_Z + drift * 0.75;
    spinWheels(redCar, drift * 0.05);
    spinWheels(blueCar, drift * 0.05);
  } else {
    t = 0;
    resetCars();
  }

  updateCamera();
  renderer.render(scene, camera);
}
animate();

window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
});
</script>
</body>
</html>
```
